import java.util.*;
public class Progression757Check {
 static void ok(boolean b,String s){if(!b)throw new AssertionError(s);System.out.println("PASS: "+s);}
 public static void main(String[] args)throws Exception{
  int[] xp={0,49,50,149,150,299,300,499,500};int[] lv={1,1,2,2,3,3,4,4,5};for(int i=0;i<xp.length;i++)ok(Progression.level(xp[i])==lv[i],"EXP boundary "+xp[i]);ok(Progression.within(100)==50&&Progression.limit(100)==100,"Loss gives Lv2 plus 50/100 EXP");ok(Progression.level(Integer.MAX_VALUE)>0&&Progression.within(Integer.MAX_VALUE)>=0,"Large EXP does not overflow");
  for(int kind=0;kind<3;kind++){CloudStore.Memory c=new CloudStore.Memory();c.register("a","password-123","A");c.register("b","password-123","B");c.register("z","password-123","Z");String a=c.login("a","password-123").userId,b=c.login("b","password-123").userId,z=c.login("z","password-123").userId;List<Map<String,Object>> p=List.of(Map.of("id",a,"team",0,"damage",10),Map.of("id",b,"team",1,"damage",10),Map.of("id",z,"team",1,"damage",0));String match=UUID.randomUUID().toString();c.settle(match,0,p,kind);c.settle(match,0,p,kind);ok(c.profile(a).experience==300&&c.profile(b).experience==100&&c.profile(z).experience==100,"EXP settlement exactly once kind "+kind);ok(c.profile(a).coins==(kind==2?1000:500)&&c.profile(b).coins==(kind==2?500:250)&&c.profile(z).coins==0,"Damage loser half coins, idle loser none kind "+kind);ok(c.rank(a)==1&&c.rank(b)==2&&c.rank(z)==2,"Server rank follows wins and ties");int prize=kind==2?500:200;ok(c.claim(match,b,0,prize)[1]==prize,"Damaging loser may claim card");int balance=c.profile(b).coins;c.claim(match,b,0,prize);ok(c.profile(b).coins==balance,"Card retry cannot duplicate money");try{c.claim(match,z,1,prize);throw new AssertionError("Idle loser claimed");}catch(IllegalArgumentException expected){} }
  ok(Progression.level(120749)==69&&Progression.level(120750)==70&&Progression.limit(120750)==0&&Progression.level(Integer.MAX_VALUE)==70,"Native level range 01 to 70 preserves cumulative EXP");http();
  ok(Progression.power(0,0)==0&&Progression.power(3,0)>Progression.power(1,0),"Power uses currently worn equipment");System.out.println("All progression 7.5.7 checks passed");
 }
 static void http()throws Exception{CloudStore.Memory store=new CloudStore.Memory();store.register("a@http757.test","test-password-123","Winner");store.register("b@http757.test","test-password-123","Loser");try(GunnyServer server=new GunnyServer(new java.net.InetSocketAddress("127.0.0.1",0),java.nio.file.Path.of("backend/assets"),store)){ServerCheck.base="http://127.0.0.1:"+server.port();String a=Equipment718ServerCheck.login("a@http757.test"),b=Equipment718ServerCheck.login("b@http757.test");int roomId=Equipment718ServerCheck.call(a,"create",out->{out.writeByte(0);out.writeByte(0);out.writeByte(-1);}).readInt();Equipment718ServerCheck.call(b,"join",out->{out.writeInt(roomId);out.writeByte(1);});Equipment718ServerCheck.call(a,"start",null);var room=server.rooms.get(roomId);synchronized(room){room.phase=2;room.battle.over=true;room.battle.winner=0;room.battle.damage[0]=10;room.battle.damage[1]=10;server.queueSettlement(room);}long end=System.currentTimeMillis()+5000;while(!room.settled&&System.currentTimeMillis()<end)Thread.sleep(10);ok(room.settled,"HTTP match settles with authoritative damage");var profile=server.sessions.get(b).profile;ok(profile.coins==250&&profile.experience==100,"HTTP loser receives half money and 100 EXP");var reply=Equipment718ServerCheck.call(b,"claim",out->out.writeByte(0));reply.readUnsignedByte();int prize=reply.readUnsignedShort();ok(profile.coins==250+prize,"HTTP damaging loser can open a reward card");Equipment718ServerCheck.call(b,"claim",out->out.writeByte(0));ok(profile.coins==250+prize,"HTTP repeated card request is idempotent");reply=Equipment718ServerCheck.call(b,"progress",null);ok(reply.readInt()==100&&reply.readInt()==0&&reply.readInt()==2,"HTTP progress returns saved EXP, lifetime wins and rank");server.sessions.get(b).profile.wins=1;ok(store.rank(profile.id)==1,"Equal wins share rank");store.register("c@http757.test","test-password-123","Third");ok(store.rank(store.login("c@http757.test","test-password-123").userId)==3,"Rank counts every player with more wins");}}

}
